// Wars and Fronts Pt.2. "All the stats should be able to be manually done by
// the scenario designer or generated by the ai." In a game, a country with no
// military figures of its own is rated in the request that already reads its
// backend when it comes into conflict with the player (conflictBackends.js).
// In the Workshop the designer may ask for them outright: "Fill in with AI" on
// a country's Military block asks this one request, for that one country,
// and fills the fields the designer left empty with what it says.
//
// Its figures are the game's own (runtime/militaryStats.js): quality,
// technology, land, sea and air from 0 to 100 (50 an ordinary army of its era;
// an arm at 0 is none at all), the share of its people who can be put under
// arms, and the shares of its army that are horse and siege.

import { normalizeMilitaryStats } from "../../runtime/militaryStats.js";
import { ERA_LABELS } from "../../runtime/warSettings.js";

const clean = (value) => String(value ?? "").replace(/\s+/g, " ").trim();

// The request.
//   name         the country's name, exactly as the scenario has it
//   note         what its author wrote of it, or ""
//   population   its people, where the author gave them
//   date         the scenario's date, or ""
//   era          the era its wars are fought in, 0 to 3, or null
//   rules        the scenario's own rules of its world, or ""
export const militaryRatingRequest = ({ name = "", note = "", population = 0, date = "", era = null, rules = "" } = {}) => {
  const systemPrompt = [
    "You are Open Historia's military assessor. Rate how the polity you are given makes war, for the game's battle engine. Each of these is a whole number from 0 to 100, where 50 is an ordinary army of its era:",
    "quality: how well its soldiers fight (a peasant levy or raw conscripts about 20, professional regulars 60 to 70, a renowned elite such as knights, legions or guards 80 and up).",
    "technology: what they fight with, against the best of its era (backward 20, ordinary 50, the most advanced 80 and up).",
    "land, sea, air: what it can do on land, at sea and in the air. 0 means it cannot fight there at all: a people that never goes to sea has sea 0; before aircraft every polity has air 0.",
    "And: manpowerShare, the percent of its people who can be put under arms (12 is ordinary; a warrior people or an order of fighting men far more); cavalryShare and siegeShare, the shares of its army that are horse (armour in modern times) and siege engines (artillery), each from 0 to 1.",
    "Go by the era, the world as described and what is said of the polity. Leave out a figure you cannot judge.",
    "",
    "Return exactly one JSON object and no markdown:",
    '{"military":{"quality":50,"technology":50,"land":50,"sea":50,"air":50,"manpowerShare":12,"cavalryShare":0.15,"siegeShare":0.1}}',
  ].join("\n");
  const people = Number(population);
  const userMessage = [
    `The polity: ${clean(name)}`,
    clean(note) ? `What the scenario says of it: ${clean(note).slice(0, 1200)}` : "",
    people >= 1 ? `Its people: ${Math.round(people)}` : "",
    clean(date) ? `The scenario's date: ${clean(date)}` : "",
    Number.isInteger(era) ? `The era its wars are fought in: ${ERA_LABELS[era]}` : "",
    clean(rules) ? `ERA & WORLD RULES:\n${String(rules).trim().slice(0, 1800)}` : "",
  ].filter(Boolean).join("\n");
  return { systemPrompt, userMessage };
};

// The answer's figures, held in range; null for none usable.
export const readMilitaryRating = (payload) => normalizeMilitaryStats(payload?.military ?? payload);

// One request, for one country. Resolves to its figures, or throws when the AI could not be asked or said nothing usable.
export const rateMilitaryFigures = async (options) => {
  const { systemPrompt, userMessage } = militaryRatingRequest(options);
  const [{ callAI }, { extractJsonPayload }] = await Promise.all([import("./main.jsx"), import("./jsonSalvage.js")]);
  const response = await callAI(systemPrompt, [{ role: "user", parts: [{ text: userMessage }] }], { reasoningEnabled: false, logLabel: "military figures" });
  const rawText = typeof response === "string" ? response : clean(response?.rawText);
  const figures = readMilitaryRating(response?.toolInput ?? extractJsonPayload(rawText));
  if (!figures) throw new Error("The AI's answer had no figures the game could use.");
  return figures;
};
